std::vector<std::string> planets = {"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"};
std::vector<std::string> result;

// Check if either planet name is invalid
auto it1 = std::find(planets.begin(), planets.end(), planet1);
auto it2 = std::find(planets.begin(), planets.end(), planet2);

if (it1 == planets.end() || it2 == planets.end()) {
    return result;
}

// Determine the order: if planet1 comes before planet2 in the solar system
bool isPlanet1BeforePlanet2 = (it1 - planets.begin()) < (it2 - planets.begin());

// If planet1 is before planet2, we take planets from it1+1 to it2
// If planet2 is before planet1, we take planets from it2+1 to it1
if (isPlanet1BeforePlanet2) {
    for (int i = it1 - planets.begin() + 1; i < it2 - planets.begin(); i++) {
        result.push_back(planets[i]);
    }
} else {
    for (int i = it2 - planets.begin() + 1; i < it1 - planets.begin(); i++) {
        result.push_back(planets[i]);
    }
}

return result;

