    std::string op_str = op[i];
    long next_val = operand[i + 1];

    if (op_str == "+") {
        result += next_val;
    } else if (op_str == "-") {
        result -= next_val;
    } else if (op_str == "*") {
        result *= next_val;
    } else if (op_str == "//") {
        result /= next_val;
    } else if (op_str == "**") {
        result = static_cast<long>(std::pow(result, next_val));
    }
}

return result;

